using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using UnityEngine;
using UnityEngine.AI;
using UnityEngine.SceneManagement;

namespace Starfall {
 public sealed class LostRealmVerification:MonoBehaviour {
  readonly List<string> report=new List<string>();CampaignRuntime campaign;SceneDirector director;int failures,baselineObjects;float lastFrameMs,baselineFrameMs;
  void Check(string label,bool good){report.Add((good?"PASS ":"FAIL ")+label);if(!good)failures++;Debug.Log("LOST_REALM_QA "+report[report.Count-1]);}
  IEnumerator WaitFor(Func<bool> predicate,float limit=15){float end=Time.realtimeSinceStartup+limit;while(!predicate()&&Time.realtimeSinceStartup<end)yield return null;Check("Transition completed",predicate());}
  IEnumerator Start(){if(!Array.Exists(Environment.GetCommandLineArgs(),a=>a=="-lostRealmQA"))yield break;yield return new WaitForSeconds(2);campaign=CampaignRuntime.Current;director=GetComponent<SceneDirector>();baselineObjects=FindObjectsByType<GameObject>(FindObjectsInactive.Include,FindObjectsSortMode.None).Length;int oldVsync=QualitySettings.vSyncCount,oldFrameTarget=Application.targetFrameRate;QualitySettings.vSyncCount=0;Application.targetFrameRate=-1;
   try{yield return Run();}finally{QualitySettings.vSyncCount=oldVsync;Application.targetFrameRate=oldFrameTarget;var path=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../QA/Reports/LostRealms"));Directory.CreateDirectory(path);File.WriteAllLines(Path.Combine(path,"lost-realms-report.txt"),report);Debug.Log(failures==0?"LOST_REALM_QA_PASS":"LOST_REALM_QA_FAIL "+failures);Application.Quit(failures==0?0:2);}
  }
  void Warp(Vector3 point){var fps=campaign.Explorer;fps.Motor.enabled=false;fps.transform.position=point;fps.Motor.enabled=true;fps.ResetMotion();Physics.SyncTransforms();}
  IEnumerator Shot(string name){yield return new WaitForEndOfFrame();var camera=campaign.Explorer.viewCamera;var target=RenderTexture.GetTemporary(1600,900,24);var previousTarget=camera.targetTexture;var previousActive=RenderTexture.active;Texture2D texture=null;try{camera.targetTexture=target;camera.Render();RenderTexture.active=target;texture=new Texture2D(1600,900,TextureFormat.RGB24,false);texture.ReadPixels(new Rect(0,0,1600,900),0,0);texture.Apply();var path=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../QA/Reports/LostRealms"));Directory.CreateDirectory(path);File.WriteAllBytes(Path.Combine(path,name+".png"),texture.EncodeToPNG());Check("Rendered screenshot "+name,true);}catch(Exception e){Debug.LogWarning("Visual capture unavailable "+e.Message);Check("Rendered screenshot "+name,false);}finally{camera.targetTexture=previousTarget;RenderTexture.active=previousActive;RenderTexture.ReleaseTemporary(target);if(texture)Destroy(texture);}}
  IEnumerator CampShot(){yield return null;yield return new WaitForEndOfFrame();var camera=director.worldCamera;var target=RenderTexture.GetTemporary(1600,900,24);var old=camera.targetTexture;var active=RenderTexture.active;Texture2D texture=null;try{camera.targetTexture=target;camera.Render();RenderTexture.active=target;texture=new Texture2D(1600,900,TextureFormat.RGB24,false);texture.ReadPixels(new Rect(0,0,1600,900),0,0);texture.Apply();var path=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../QA/Reports/LostRealms"));File.WriteAllBytes(Path.Combine(path,"06-expanded-camp.png"),texture.EncodeToPNG());Check("Rendered expanded camp",true);}catch(Exception e){Debug.LogWarning(e.Message);Check("Rendered expanded camp",false);}finally{camera.targetTexture=old;RenderTexture.active=active;RenderTexture.ReleaseTemporary(target);if(texture)Destroy(texture);}}
  IEnumerator FrameProbe(string label){yield return new WaitForSecondsRealtime(.5f);var camera=campaign.Explorer.viewCamera;var target=RenderTexture.GetTemporary(1600,900,24);var previousTarget=camera.targetTexture;var previousActive=RenderTexture.active;var pixel=new Texture2D(1,1,TextureFormat.RGB24,false);var samples=new List<float>();try{camera.targetTexture=target;RenderTexture.active=target;for(int i=0;i<32;i++){var watch=System.Diagnostics.Stopwatch.StartNew();camera.Render();pixel.ReadPixels(new Rect(799,449,1,1),0,0);pixel.Apply(false);watch.Stop();if(i>=4)samples.Add((float)watch.Elapsed.TotalMilliseconds);yield return null;}}finally{camera.targetTexture=previousTarget;RenderTexture.active=previousActive;RenderTexture.ReleaseTemporary(target);Destroy(pixel);}samples.Sort();float sum=0;for(int i=5;i<samples.Count-5;i++)sum+=samples[i];lastFrameMs=sum/(samples.Count-10);report.Add("METRIC "+label+" 1600x900 camera render ms "+lastFrameMs.ToString("F2"));}
  IEnumerator Visit(int region,string scene){if(!campaign.State.coordinates.Contains(region))campaign.State.coordinates.Add(region);Check("Enter region "+region,campaign.EnterRegion(region));yield return WaitFor(()=>campaign.Explorer&&!director.battle.IsTransitioning,20);Check("Dedicated scene "+region,SceneManager.GetActiveScene().name==scene);Check("Return beacon "+region,campaign.Explorer.returnBeacon!=null);Check("All side sites navigable "+region,campaign.RegionView.ExpansionSitesReachable());
   var nav=new NavMeshPath();var from=campaign.Explorer.returnBeacon.position;var to=region==5?new Vector3(0,0,19):new Vector3(-6,0,-22);NavMesh.SamplePosition(from,out var start,8,NavMesh.AllAreas);NavMesh.SamplePosition(to,out var goal,8,NavMesh.AllAreas);Check("Navigable main route "+region,NavMesh.CalculatePath(start.position,goal.position,NavMesh.AllAreas,nav)&&nav.status==NavMeshPathStatus.PathComplete);
  }
  IEnumerator Leave(){campaign.Explorer.Return();yield return WaitFor(()=>!director.battle.IsEngaged,15);yield return null;Check("No scene objects retained after return",Math.Abs(FindObjectsByType<GameObject>(FindObjectsInactive.Include,FindObjectsSortMode.None).Length-baselineObjects)<8);}
  void FreezeActors(){foreach(var actor in campaign.Explorer.arena.creatures)if(actor){actor.enabled=false;if(actor.Agent&&actor.Agent.isOnNavMesh){actor.Agent.ResetPath();actor.Agent.isStopped=true;}var elite=actor.GetComponent<EliteCreature>();if(elite)elite.enabled=false;}var titan=FindFirstObjectByType<TitanAreaAttack>();if(titan){titan.Cancel();titan.AttackEnabled=false;}}
  int TotalParts(){int n=campaign.State.bag.Count(ItemId.MachineParts)+campaign.State.warehouse.Count(ItemId.MachineParts);foreach(var crate in campaign.State.crates)n+=crate.items.Count(ItemId.MachineParts);return n;}
  IEnumerator RelayCheck(bool testExpiry){
   var fps=campaign.Explorer;var region=campaign.RegionView;fps.arena.SimulationEnabled=true;FreezeActors();int parts=TotalParts();
   var first=GameObject.Find("Echo relay "+region.id+" / 0");Check("Relay landmarks exist "+region.id,first!=null);if(!first)yield break;
   Warp(first.transform.position+Vector3.left*2);yield return null;Check("Reach relay through field interaction "+region.id,region.Near("relay:0")&&region.Interact()&&region.RelayMask==1);
   Check("Active receiver cannot repeat",!region.ActivateRelay(0));float remaining=region.RelayRemaining;fps.SetPaused(true);yield return new WaitForSecondsRealtime(.2f);Check("Relay window freezes on pause",Mathf.Abs(remaining-region.RelayRemaining)<.03f);fps.SetPaused(false);
   if(testExpiry){typeof(CampaignRegion).GetField("relayTime",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).SetValue(region,.05f);yield return new WaitForSeconds(.15f);Check("Expired relay resets without reward",region.RelayMask==0&&region.RelayRemaining==0&&TotalParts()==parts);Check("Relay retry is available",region.ActivateRelay(0));}
   fps.viewCamera.transform.LookAt(first.transform.position+Vector3.up*1.4f);yield return Shot("relay-"+region.id);
   for(int i=1;i<3;i++){var station=GameObject.Find("Echo relay "+region.id+" / "+i);Warp(station.transform.position+Vector3.left*2);yield return null;Check("Physical relay activation "+region.id+" / "+i,region.ActivateRelay(i));}
   Check("Relay first reward is atomic "+region.id,campaign.Exp("relay-complete-"+region.id)&&TotalParts()==parts+4&&!campaign.CompleteRelay(region.id)&&TotalParts()==parts+4);
  }
  IEnumerator EliteCheck(bool ground){
   var fps=campaign.Explorer;fps.arena.SimulationEnabled=true;FreezeActors();EliteCreature elite=null;foreach(var actor in fps.arena.creatures)if(actor&&actor.GetComponent<EliteCreature>())elite=actor.GetComponent<EliteCreature>();if(!elite)yield break;elite.enabled=true;var creature=elite.GetComponent<AlienCreature>();creature.ResumeFromElite();fps.arena.RestoreHealth(100);Warp(creature.transform.position+Vector3.left*12);yield return null;
   var flags=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;typeof(EliteCreature).GetField("cycle",flags).SetValue(elite,-1f);if(!ground)typeof(EliteCreature).GetField("diveNext",flags).SetValue(elite,false);
   yield return WaitFor(()=>elite.SpecialPhase==1,5);Check("Elite special suspends ordinary attacks "+elite.Id,!creature.enabled);
   fps.SetPaused(true);int count=elite.LightningStrikes+elite.TailSwings;yield return new WaitForSecondsRealtime(.2f);Check("Elite telegraph freezes on pause",elite.LightningStrikes+elite.TailSwings==count&&elite.SpecialPhase==1);fps.SetPaused(false);
   if(ground){yield return WaitFor(()=>elite.TailSwings==1,4);Check("Ground elite completes tail and recovers",elite.SpecialPhase==0&&creature.enabled);}
   else{yield return WaitFor(()=>elite.LightningStrikes==1,4);yield return new WaitForSeconds(.2f);Check("Lightning strikes are sequential",elite.LightningStrikes==1);yield return WaitFor(()=>elite.LightningStrikes==3,3);Check("Wing elite exposes landed counterattack window",elite.Landed&&!creature.enabled);yield return WaitFor(()=>elite.SpecialPhase==0,4);creature.enabled=false;typeof(EliteCreature).GetField("cycle",flags).SetValue(elite,-1f);yield return WaitFor(()=>elite.Dives==1,5);Check("Wing alternates lightning and dive",elite.LightningStrikes==3&&elite.Landed);}
   elite.enabled=false;creature.enabled=false;fps.arena.RestoreHealth(100);
  }
  IEnumerator PulseCheck(){
   var fps=campaign.Explorer;fps.arena.SimulationEnabled=true;FreezeActors();Warp(new Vector3(0,AlienSurfaceLandmarks.Height(0,-13),-13));yield return new WaitForSeconds(1.4f);var gun=fps.arsenal;
   AlienCreature victim=null,blocked=null;foreach(var actor in fps.arena.creatures)if(actor&&!actor.GetComponent<EliteCreature>()&&actor.kind==CreatureKind.RiftMauler&&!actor.GetComponent<CreatureVitality>().Dead){if(!victim)victim=actor;else if(!blocked)blocked=actor;}
   Check("Pulse technology unlocked by all three relays",campaign.PulseUnlocked);if(!victim||!blocked){Check("Ordinary pulse targets available",false);yield break;}
   NavMesh.SamplePosition(fps.transform.position+Vector3.left*2,out var close,5,NavMesh.AllAreas);victim.Agent.Warp(close.position);victim.transform.rotation=Quaternion.LookRotation(Vector3.left);NavMesh.SamplePosition(fps.transform.position+Vector3.forward*3.5f,out var far,5,NavMesh.AllAreas);blocked.Agent.Warp(far.position);blocked.transform.rotation=Quaternion.identity;
   var wall=GameObject.CreatePrimitive(PrimitiveType.Cube);wall.name="QA solid pulse cover";wall.transform.SetParent(fps.arena.transform);wall.transform.position=(fps.transform.position+blocked.transform.position)*.5f+Vector3.up*1.5f;wall.transform.localScale=new Vector3(2,3,.55f);Physics.SyncTransforms();
   float before=gun.Stamina;Check("Pulse consumes stamina and staggers visible ordinary foe",gun.UsePulse()&&Mathf.Abs(gun.Stamina-(before-35))<.1f&&victim.Staggered);Check("Pulse respects solid cover",!blocked.Staggered);Check("Pulse cannot repeat inside cooldown",!gun.UsePulse());
   foreach(var actor in fps.arena.creatures)if(actor&&actor.GetComponent<EliteCreature>())Check("Elite resists crowd-control pulse",!actor.PulseStagger(1));
   campaign.Save("pulse-roundtrip");var loaded=campaign.Store.Load("pulse-roundtrip");Check("Pulse cooldown survives save",loaded!=null&&loaded.pulseCooldown>17);float cooldown=gun.PulseCooldown;fps.SetPaused(true);yield return new WaitForSecondsRealtime(.2f);Check("Pulse cooldown freezes on pause",Mathf.Abs(gun.PulseCooldown-cooldown)<.02f);fps.SetPaused(false);Destroy(wall);
  }
  IEnumerator ShipyardDeckCheck(){
   var fps=campaign.Explorer;fps.arena.SimulationEnabled=true;FreezeActors();var relic=GameObject.Find("Fleet insignia");Check("Shipyard relic is on raised deck",relic&&relic.transform.position.y>AlienSurfaceLandmarks.Height(relic.transform.position.x,relic.transform.position.z)+1);if(!relic)yield break;
   var path=new NavMeshPath();NavMesh.SamplePosition(fps.returnBeacon.position,out var entry,8,NavMesh.AllAreas);bool navigable=NavMesh.CalculatePath(entry.position,relic.transform.position,NavMesh.AllAreas,path)&&path.status==NavMeshPathStatus.PathComplete;Check("Shipyard ramps connect to deck",navigable);if(!navigable)yield break;
   Warp(entry.position);int steps=0;foreach(var corner in path.corners){while(CreatureArena.FlatDistance(fps.transform.position,corner)>.65f&&steps++<1900){var direction=corner-fps.transform.position;direction.y=0;direction.Normalize();fps.Drive(new Vector2(Vector3.Dot(direction,fps.transform.right),Vector3.Dot(direction,fps.transform.forward)),false,false,1/60f);Physics.SyncTransforms();yield return null;}}
   report.Add("ROUTE shipyard motor="+fps.transform.position+" relic="+relic.transform.position+" steps="+steps+" corners="+string.Join(";",Array.ConvertAll(path.corners,p=>p.ToString())));Check("Character collision motor walks both shipyard ramps",Vector3.Distance(fps.transform.position,relic.transform.position)<3.5f);fps.viewCamera.transform.LookAt(relic.transform.position+Vector3.up);yield return Shot("shipyard-upper-deck");yield return null;Check("Upper floor relic interaction is reachable",campaign.RegionView.Near("relic-4")&&campaign.RegionView.Interact()&&campaign.Exp("relic-4"));
   Check("Lower floor query ignores overhead deck",Mathf.Abs(FieldSurface.Height(22,26,AlienSurfaceLandmarks.Height(17,19)+2)-(AlienSurfaceLandmarks.Height(17,19)+2))<.1f);var drop=fps.expedition.AddDrop(BasinLootKind.Ammo,fps.transform.position+fps.transform.forward);Check("Drop stays on reachable upper floor",drop&&drop.transform.position.y>AlienSurfaceLandmarks.Height(drop.transform.position.x,drop.transform.position.z)+1);Check("Upper floor drop can be collected",drop&&fps.expedition.Collect(drop));
  }
  IEnumerator Run(){
   Check("Content catalog present",LostRealmCatalog.Current&&LostRealmCatalog.Current.weapons.Length==3&&LostRealmCatalog.Current.modules.Length==4&&LostRealmCatalog.Current.quests.Length==6);Check("Relay and relic catalogs complete",LostRealmCatalog.Current.relays.Length==3&&LostRealmCatalog.Current.relics.Length==5);
   var temporary=new CampaignStore(Path.Combine(Application.persistentDataPath,"LostRealmMigrationQA"));var old=CampaignState.New();old.version=1;old.bag.Add(ItemId.CobaltOre,7);old.crates.Add(new SavedCrate{id="legacy-crate",region=2,items=new ItemContainer(48)});old.crates[0].items.Add(ItemId.Fuel,3);temporary.Save(old,"legacy");var restored=temporary.Load("legacy");Check("Version-one inventory migrates",restored!=null&&restored.version==2&&restored.bag.Count(ItemId.CobaltOre)==7&&restored.crates[0].items.Count(ItemId.Fuel)==3);Check("Version-one file retained",Directory.GetFiles(temporary.directory,"legacy.json.v1-*.json").Length>0);
   director.battle.Enter(null);yield return WaitFor(()=>campaign.Explorer&&!director.battle.IsTransitioning,20);yield return FrameProbe("Original basin");baselineFrameMs=lastFrameMs;yield return Leave();
   yield return Visit(1,"Scene03_WreckRift");yield return FrameProbe("Wreck rift");yield return Shot("01-wreck");Check("First rift preserves two ground dragons",campaign.Explorer.arena.creatures.Length==2);
   var mast=GameObject.Find("Signal mast A");if(mast){Warp(mast.transform.position+Vector3.left*2);yield return null;Check("Reach antenna in first-person",campaign.RegionView.Near("antenna-0"));Check("First-person E repairs antenna",campaign.RegionView.Interact()&&campaign.Exp("antenna-0"));Check("Restored antenna remains in scene",mast&&mast.GetComponent<RegionDeviceVisual>().Completed);}else Check("Antenna exists",false);
   campaign.Explorer.arena.SimulationEnabled=false;for(int i=1;i<3;i++)campaign.ExpansionInteract("antenna-"+i);Check("Drone unlock and scan",campaign.Exp("drone-rescued")&&campaign.ScanUnlocked);campaign.ExpansionInteract("relic-1");yield return Leave();
   var stranded=new SavedCrate{id="legacy-stranded-realm-crate",region=2,position=new Vector3(8000,8000,8000),items=new ItemContainer(48)};stranded.items.Add(ItemId.Fuel,3);campaign.State.crates.Add(stranded);campaign.State.magazine=5;
   yield return Visit(2,"Scene04_Battlefield");yield return null;Check("Unreachable old crate returns to camp intact",stranded.region==0&&stranded.items.Count(ItemId.Fuel)==3);Check("Relocation does not reset loaded ammo",campaign.State.magazine==5);yield return FrameProbe("Battlefield");yield return Shot("02-battlefield");Check("Battlefield elite present",Array.Exists(campaign.Explorer.arena.creatures,c=>c&&c.GetComponent<EliteCreature>()&&c.GetComponent<EliteCreature>().Id=="ground"));campaign.Explorer.arena.SimulationEnabled=false;
   campaign.ExpansionInteract("winch");campaign.ExpansionInteract("shelter");Check("Engineer unlocks scattergun",campaign.WeaponUnlocked(1)&&campaign.Exp("engineer-rescued"));campaign.ExpansionInteract("signal-0");campaign.ExpansionInteract("cache-2-0");int parts=campaign.State.bag.Count(ItemId.MachineParts);campaign.ExpansionInteract("cache-2-0");Check("Supply box cannot duplicate",campaign.State.bag.Count(ItemId.MachineParts)==parts);campaign.ExpansionInteract("relic-2");yield return EliteCheck(true);yield return RelayCheck(true);
   campaign.Explorer.arena.SimulationEnabled=true;foreach(var actor in campaign.Explorer.arena.creatures)if(actor)actor.enabled=false;Warp(new Vector3(0,AlienSurfaceLandmarks.Height(0,-13),-13));yield return null;var gun=campaign.Explorer.arsenal;Check("Equip scattergun",gun.SelectWeapon(1));Check("Scatter consumes two loaded rounds",gun.Attack()&&gun.ShotgunMagazine==6);yield return new WaitForSeconds(.8f);int beforeAmmo=gun.Reserve;Check("Scatter reload begins",gun.Reload());yield return WaitFor(()=>gun.ReloadRemaining<=0,4);Check("Scatter reload conserves ammunition",gun.ShotgunMagazine==8&&gun.Reserve==beforeAmmo-2);campaign.Explorer.arena.SimulationEnabled=false;yield return Leave();
   yield return Visit(3,"Scene05_Medical");yield return FrameProbe("Medical");yield return Shot("03-medical");campaign.Explorer.arena.SimulationEnabled=false;campaign.ExpansionInteract("power");campaign.ExpansionInteract("medical-door");campaign.ExpansionInteract("sample-0");campaign.ExpansionInteract("sample-1");campaign.ExpansionInteract("signal-1");Check("Doctor and samples persist",campaign.Exp("doctor-rescued")&&campaign.Exp("sample-1"));campaign.ExpansionInteract("relic-3");yield return RelayCheck(false);
   foreach(var actor in campaign.Explorer.arena.creatures)if(actor)actor.enabled=false;campaign.Explorer.arena.SimulationEnabled=true;typeof(CampaignRegion).GetField("eventClock",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).SetValue(campaign.RegionView,.01f);yield return new WaitForSeconds(3.5f);Check("Resonance reveals collectable veins",GameObject.Find("Resonance cobalt seam 0")!=null);campaign.Explorer.arena.SimulationEnabled=false;yield return Leave();
   yield return Visit(4,"Scene06_Shipyard");yield return FrameProbe("Shipyard");yield return Shot("04-shipyard");Check("Shipyard elite present",Array.Exists(campaign.Explorer.arena.creatures,c=>c&&c.GetComponent<EliteCreature>()&&c.GetComponent<EliteCreature>().Id=="wing"));campaign.Explorer.arena.SimulationEnabled=false;
   campaign.ExpansionInteract("crane");campaign.ExpansionInteract("signal-2");campaign.ExpansionInteract("sample-2");Check("Railgun and greenhouse unlock",campaign.WeaponUnlocked(2)&&campaign.Exp("greenhouse")&&campaign.Exp("signals-complete"));yield return EliteCheck(false);yield return RelayCheck(false);yield return ShipyardDeckCheck();
   campaign.Explorer.arena.SimulationEnabled=true;foreach(var actor in campaign.Explorer.arena.creatures)if(actor)actor.enabled=false;Warp(new Vector3(0,AlienSurfaceLandmarks.Height(0,-13),-13));yield return null;var railgun=campaign.Explorer.arsenal;Check("Equip railgun",railgun.SelectWeapon(2));int originalRounds=railgun.RailMagazine;Check("Rail charge begins without spending ammo",railgun.Attack()&&railgun.RailMagazine==originalRounds);yield return new WaitForSeconds(1.1f);Check("Charged rail shot spends three loaded rounds",railgun.RailMagazine==originalRounds-3);yield return PulseCheck();
   typeof(CampaignRegion).GetField("eventClock",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).SetValue(campaign.RegionView,.01f);yield return new WaitForSeconds(3.5f);Check("Electromagnetic pulse opens side barrier",GameObject.Find("Power barrier · optional cargo shortcut")==null);campaign.Explorer.arena.SimulationEnabled=false;yield return Leave();
   director.player.position=new Vector3(director.camp.transform.position.x,director.surfaceY,0);campaign.State.warehouse.Add(ItemId.MachineParts,20);
   Check("Craft four distinct modules",campaign.CraftModule("stamina")&&campaign.CraftModule("reload")&&campaign.CraftModule("magnet")&&campaign.CraftModule("weakness")&&!campaign.CraftModule("stamina"));
   Check("Two module slots enforced",campaign.ToggleModule("stamina")&&campaign.ToggleModule("reload")&&!campaign.ToggleModule("magnet"));
   yield return CampShot();
   int held=campaign.State.bag.Count(ItemId.MachineParts)+campaign.State.warehouse.Count(ItemId.MachineParts);campaign.Save("expansion-roundtrip");var loaded=campaign.Store.Load("expansion-roundtrip");Check("Expansion roundtrip",loaded!=null&&loaded.craftedModules.Count==4&&loaded.equippedModules.Count==2&&loaded.expansionProgress.Contains("greenhouse")&&loaded.bag.Count(ItemId.MachineParts)+loaded.warehouse.Count(ItemId.MachineParts)==held);
   yield return Visit(5,"Scene07_Core");yield return FrameProbe("Core");yield return Shot("05-core");Check("Core boss retained",campaign.RegionView.boss!=null);campaign.ExpansionInteract("relic-5");yield return Leave();director.player.position=new Vector3(director.camp.transform.position.x,director.surfaceY,0);Check("All five relics restore observatory once",campaign.RelicCount==5&&campaign.RestoreAtlas()&&!campaign.RestoreAtlas());yield return CampShot();director.player.position=new Vector3(-11.5f,director.surfaceY,0);campaign.State.health=50;yield return null;Check("Doctor direct camp interaction",campaign.SurfaceInteract()&&campaign.Modal);Check("Doctor starts treatment inside companion view",campaign.StartTreatment());yield return new WaitForSecondsRealtime(3.2f);Check("Companion treatment completes",campaign.State.health==100);campaign.Close();campaign.TrackObjective("quest:0");Check("Completed tracked quest falls back to main objective",campaign.TrackedHint=="");campaign.TrackObjective("relics");campaign.Save("voyage-roundtrip");var voyage=campaign.Store.Load("voyage-roundtrip");Check("Voyage progress and cooldown survive save",voyage!=null&&voyage.expansionProgress.Contains("atlas-restored")&&voyage.expansionProgress.Contains("relay-complete-4")&&Mathf.Abs(voyage.pulseCooldown-campaign.State.pulseCooldown)<.01f);var invalid=CampaignState.New();invalid.craftedModules.Add("stamina");invalid.equippedModules.Add("stamina");invalid.equippedModules.Add("stamina");temporary.Save(invalid,"duplicate-module");Check("Duplicate equipped module save rejected",temporary.Load("duplicate-module")==null);
  }
 }
